<script setup>
import {ref,computed,watch} from 'vue'
import {request} from '../session'
import {useData,action,modes} from '../data'
import {t} from '../i18n'
import ContactSelect from '../components/ContactSelect.vue'
const page=ref(1),query=useData(()=>`/api/v1/campaigns?page=${page.value}&size=50`),system=useData('/api/v1/admin/system-overview'),templates=useData('/api/v1/script-templates?page=1&size=200'),open=ref(false),editing=ref(null),model=ref({}),busy=ref(false),flows=useData(()=>open.value&&model.value.script_template_id?`/api/v1/script-templates/${model.value.script_template_id}/flows`:'')
const capacity=computed(()=>system.data.value?.capacity?.effective_max_concurrent_calls)
const fields=computed(()=>[{key:'name',label:'name',required:true},{key:'mode',label:'mode',required:true,options:modes.map((value,i)=>({value,label:['aiOnly','aiHandoff','humanOnly','aiWithSms'][i]}))},{key:'voice_ai_pipeline',label:'voiceAiPipeline',options:['inherit','legacy','pipecat'],wide:true,hint:'voiceAiPipelineHint'},{key:'contact_ids',label:'contactsSelected',required:true,wide:true},{key:'script_template_id',label:'scriptTemplate',options:(templates.data.value||[]).map(v=>({value:v.id,label:v.name}))},{key:'script_flow_version_id',label:'已发布话术画布',disabled:!model.value.script_template_id,options:(flows.data.value||[]).filter(v=>v.status==='published').map(v=>({value:v.id,label:`${v.name} · v${v.version}`})),hint:'任务锁定具体发布版本；后续草稿修改不会影响运行中的外呼。'},{key:'script',label:'content',type:'textarea',rows:5},{key:'concurrency',label:'concurrency',type:'number',min:1,max:capacity.value,disabled:!capacity.value},{key:'retry_limit',label:'retryLimit',type:'number',min:0,max:10},{key:'retry_interval_sec',label:'retryInterval',type:'number',min:1},{key:'attempt_interval_sec',label:'attemptInterval',type:'number',min:1},{key:'recording_enabled',label:'recording',type:'boolean'},{key:'hangup_sms_enabled',label:'hangupSms',type:'boolean'}])
function edit(row){editing.value=row;model.value=row?Object.fromEntries(fields.value.map(f=>[f.key,row[f.key]===undefined?undefined:JSON.parse(JSON.stringify(row[f.key]))])):{mode:'ai_handoff',concurrency:5,retry_limit:1,retry_interval_sec:30,attempt_interval_sec:1800,recording_enabled:true,hangup_sms_enabled:true,voice_ai_pipeline:'inherit',contact_ids:[]};open.value=true}
async function save(){busy.value=true;try{const payload={...model.value};for(const key of ['script_template_id','script_flow_version_id'])if(payload[key]==='')payload[key]=null;await action(()=>request('/api/v1/campaigns'+(editing.value?'/'+editing.value.id:''),editing.value?'PUT':'POST',payload),{refresh:query.load});open.value=false}finally{busy.value=false}}
function command(row,kind){return action(()=>request(`/api/v1/campaigns/${row.id}/${kind==='start'?'start?async_dial=true':kind}`,'POST'),{confirm:['start','stop'].includes(kind)?t(kind==='start'?'confirmStart':'confirmStop'):undefined,refresh:query.load})}
</script><template><PageHeader title="campaigns" description="campaignHint"><el-button type="primary" @click="edit()">{{t('createCampaign')}}</el-button></PageHeader><el-card><el-alert v-if="query.error.value" :title="query.error.value" type="error"/><DataGrid :rows="(query.data.value||[]).filter(row=>row.status!=='deleted')" :loading="query.loading.value" :columns="[{key:'id',label:'ID'},{key:'name',label:'name'},{key:'mode',label:'mode',translate:true},{key:'voice_ai_pipeline',label:'voiceAiPipeline'},{key:'contact_ids',label:'contactsSelected',render:value=>value?.length||0},{key:'concurrency',label:'concurrency'},{key:'status',label:'status',translate:true,tag:true},{key:'created_at',label:'createdAt',date:true}]"><template #actions="{row}"><template v-if="['draft','failed','stopped','prepared'].includes(row.status)"><el-button size="small" type="primary" @click="command(row,'start')">{{t('start')}}</el-button><el-button size="small" @click="edit(row)">{{t('edit')}}</el-button></template><el-button v-if="row.status==='running'" size="small" @click="command(row,'pause')">{{t('pause')}}</el-button><el-button v-if="row.status==='paused'" size="small" @click="command(row,'resume')">{{t('resume')}}</el-button><el-button v-if="['running','paused','prepared'].includes(row.status)" size="small" type="danger" @click="command(row,'stop')">{{t('stop')}}</el-button><el-button v-else size="small" type="danger" @click="action(()=>request('/api/v1/campaigns/'+row.id,'DELETE'),{confirm:t('confirmDelete'),refresh:query.load})">{{t('delete')}}</el-button></template></DataGrid><Pager :page="page" :count="query.data.value?.length||0" @change="page=$event"/></el-card><el-dialog v-model="open" :title="t(editing?'editCampaign':'createCampaign')" width="760px" destroy-on-close><FieldForm :model="model" :fields="fields" :busy="busy" @change="key=>{if(key==='script_template_id')model.script_flow_version_id=null}" @submit="save"><template #contact_ids><ContactSelect v-model="model.contact_ids"/></template></FieldForm></el-dialog></template>
